			dw kw_printzoscii
			dw glyph_54, glyph_6F, glyph_74, glyph_61, glyph_6C, 0		; "Total"
			dw kw_l_printvb, var_total
			dw kw_scpgtvv, arr_sc+2, arr_sc+4
			dw kw_ftov, tmp0
