ch16_e_go:			ld sp, ch16_e
			jp ntc_xn
ch17_e_go:			ld sp, ch17_e
			jp ntc_xn
ln_1000_gs:			ld (ln_1000_rs), sp
			ld sp, ln_1000
			jp ntc_xn
ln_1000_rt:			ld sp, (ln_1000_rs)
			jp ntc_xn
ln_1020_gs:			ld (ln_1020_rs), sp
			ld sp, ln_1020
			jp ntc_xn
ln_1020_rt:			ld sp, (ln_1020_rs)
			jp ntc_xn

p_fn_pct_c:		; call fn_pct (normal)
			pop hl			; x
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_fn_pct_x), de
			ld hl, 0
			ld (var_fn_pct_fn_pct), hl
			ld (p_fn_pct_rs), sp
			ld sp, p_fn_pct
			jp ntc_xn
p_fn_pct_r:		; end of fn_pct
			ld sp, (p_fn_pct_rs)
			jp ntc_xn

